import re
def uuid_bytes(uuid_str):
    if not re.match(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', uuid_str):
        raise ValueError("Invalid UUID format")
    hex_str = uuid_str.replace('-', '')
    return bytes.fromhex(hex_str)
